    let owner = ctx.db.owner().identity().find(ctx.sender()).is_some();
    RawQuery::new(format!("SELECT * FROM staff_member{}", if owner { "" } else { " WHERE id = 0" }))
}

pub fn my_owner(ctx: &ViewContext) -> Vec<Owner> {
